INSERT INTO "passive_skill_sets" ("id","name","itemized_description","sougou_only_itemized_description","kobetu_only_itemized_description","created_at","updated_at") VALUES (1950000003,'Strongest Duo','*Basic effect(s)*
- ATK & DEF 300%{passiveImg:up_g}
- High chance of performing a critical hit
- Great chance of evading enemy''s attack
- Randomly changes Ki Spheres of a certain Type (INT & PHY
excluded) to Rainbow Ki Spheres
- Receives an additional Ki +1 per Type Ki Sphere obtained
- Receives an additional Ki +3 per Rainbow Ki Sphere obtained
- Damage reduction rate 30%{passiveImg:up_g}
- Super Class allies'' ATK & DEF 40%{passiveImg:up_g}
- Extreme Class enemies'' ATK & DEF 30%{passiveImg:down_y}
*When attacking*
- ATK & DEF 300%{passiveImg:up_g}
*For 4 turns from the character''s entry turn*
- Damage reduction rate 30%{passiveImg:up_g}
- Launches an additional Super Attack
*Starting from the 5th turn from the start of battle, or when HP
is 50% or less*
- Performs Potara Fusion',NULL,NULL,'2026-10-14 02:33:34','2026-10-19 14:03:31');
